package com.medicore.notification.entity; import jakarta.persistence.*; @Entity @Table(name="notifications") public class Notification {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long userId; @Column(nullable=false) private String message; @Column(nullable=false) private String status="PENDING"; protected Notification(){} public Notification(Long userId,String message){this.userId=userId;this.message=message;} public Long getId(){return id;} public Long getUserId(){return userId;} public String getMessage(){return message;} public String getStatus(){return status;} public void setStatus(String s){status=s;}}
